    group('ロック', 'locked', [[true, 'ロック中'], [false, 'なし']], y + 290);
    group('お気に入り', 'favorite', [[true, '★のみ']], y + 348);
    group('相棒', 'partner', [[true, '相棒のみ']], y + 406);
