  Txt(TR_RULES, 36, 600, 488, 12, SOFT, hp, { lh: 1.55 }).classList.add('tr-rules');
  // ② the menus (2 × 2), one is chosen; then one CTA
  const mp = Glass('Training menus', 620, 134, 944, 676, undefined, .86);
