const hiQuery = (tab, cursor) => (tab === 'purchases' ? ['purchases', { cursor, limit: HI_PAGE }] : tab === 'gacha' ? ['gacha', { cursor, limit: HI_PAGE }] : ['coins', { cursor, limit: HI_PAGE, currency: tab === 'coins_paid' ? 'paid' : 'free' }]);
